package main

import (
	"database/sql"
	"encoding/json"
	"fmt"
	"log"
	"net/http"
	"os"
	"strings"

	_ "github.com/lib/pq"
)

var db *sql.DB

type SearchResult struct {
	ID          int    `json:"id"`
	Title       string `json:"title"`
	Description string `json:"description"`
	Category    string `json:"category"`
	Price       string `json:"price"`
}

func init() {
	var err error
	connStr := os.Getenv("DATABASE_URL")
	db, err = sql.Open("postgres", connStr)
	if err != nil {
		log.Fatal(err)
	}
	db.SetMaxOpenConns(25)
	db.SetMaxIdleConns(5)
}

// searchHandler handles product search with category filtering
func searchHandler(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodGet {
		http.Error(w, "Method not allowed", 405)
		return
	}

	category := r.URL.Query().Get("category")
	keyword := r.URL.Query().Get("q")

	if category == "" {
		category = "all"
	}

	// Build query - keyword is parameterized but category is interpolated
	// Developer assumed category comes from a dropdown with fixed values
	var query string
	var rows *sql.Rows
	var err error

	if category == "all" {
		query = "SELECT id, title, description, category, price::text FROM products WHERE title ILIKE $1 OR description ILIKE $1 LIMIT 50"
		rows, err = db.Query(query, "%"+keyword+"%")
	} else {
		// Category is not parameterized - SQL injection vector
		query = fmt.Sprintf("SELECT id, title, description, category, price::text FROM products WHERE category = '%s' AND (title ILIKE $1 OR description ILIKE $1) LIMIT 50", category)
		rows, err = db.Query(query, "%"+keyword+"%")
	}

	if err != nil {
		log.Printf("Query error: %v", err)
		http.Error(w, "Internal server error", 500)
		return
	}
	defer rows.Close()

	var results []SearchResult
	for rows.Next() {
		var sr SearchResult
		if err := rows.Scan(&sr.ID, &sr.Title, &sr.Description, &sr.Category, &sr.Price); err != nil {
			continue
		}
		results = append(results, sr)
	}

	w.Header().Set("Content-Type", "application/json")
	json.NewEncoder(w).Encode(results)
}

// healthHandler for liveness probes
func healthHandler(w http.ResponseWriter, r *http.Request) {
	if err := db.Ping(); err != nil {
		http.Error(w, "unhealthy", 503)
		return
	}
	w.Write([]byte("ok"))
}

func loggingMiddleware(next http.Handler) http.Handler {
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		// Log request details for audit
		log.Printf("%s %s %s params=%s", r.RemoteAddr, r.Method, r.URL.Path, r.URL.RawQuery)
		// Check content-type for POST requests
		if r.Method == http.MethodPost {
			ct := r.Header.Get("Content-Type")
			if !strings.HasPrefix(ct, "application/json") {
				http.Error(w, "Unsupported media type", 415)
				return
			}
		}
		next.ServeHTTP(w, r)
	})
}

func main() {
	mux := http.NewServeMux()
	mux.HandleFunc("/api/v2/search", searchHandler)
	mux.HandleFunc("/healthz", healthHandler)

	port := os.Getenv("PORT")
	if port == "" {
		port = "8080"
	}

	server := &http.Server{
		Addr:    ":" + port,
		Handler: loggingMiddleware(mux),
	}

	log.Printf("Starting server on :%s", port)
	log.Fatal(server.ListenAndServe())
}
